with scored as (select *, last_value(unit_price, true) over (order by quantity, id rows between unbounded preceding and current row) as last_known_unit_price, lead(quantity, 1) over (partition by order_id order by unit_price, id) as next_quantity, last_value(unit_price, true) over w_recent as last_known_unit_price_2 from order_items window w_recent as (partition by product_id order by quantity, id rows between unbounded preceding and current row)), with_dims as (select s.*, o.shipping_fee, o.status, o.amount from scored s inner join orders o on s.order_id = o.id), ranked as (select * from with_dims qualify row_number() over (partition by status order by amount, id) = 1) select case when last_known_unit_price_2 >= 380 then 'PREMIUM' else 'STANDARD' end as last_known_unit_price_2_tier, percentile_approx(shipping_fee, 0.5) as shipping_fee_p50, count(case when status = 'CANCELLED' then 1 end) as cancelled_count, sum(case when status = 'PENDING' then shipping_fee else 0 end) as pending_shipping_fee from ranked group by case when last_known_unit_price_2 >= 380 then 'PREMIUM' else 'STANDARD' end
